/* @lc app=leetcode id=3685 lang=kotlin */ class Solution { fun subsequenceSumAfterCapping(nums: IntArray, k: Int): BooleanArray = nums.size.let { n -> IntArray(n + 1).also { c -> nums.forEach { c[it]++ } }.let { cv -> BooleanArray(k + 1).also { it[0] = true }.let { dp -> (1..n).fold(0 to listOf<Boolean>()) { (le, acc), x -> repeat(cv[x]) { (k downTo x).forEach { s -> if (dp[s - x]) dp[s] = true } }.let { (le + cv[x]).let { nle -> nle to acc + (0..minOf(n - nle, k / x)).any { t -> dp[k - t * x] } } } }.second.toBooleanArray() } } } }